begin;

on conflict (id) do update set name = excluded.name, sort_order = excluded.sort_order, combat_weight = excluded.combat_weight, modality = excluded.modality;

on conflict (id) do update set name = excluded.name, modality = excluded.modality, load_type = excluded.load_type, equipment = excluded.equipment, variation_of_id = excluded.variation_of_id, reference_pace_s_per_km = excluded.reference_pace_s_per_km, pace_unit = excluded.pace_unit, max_effort = excluded.max_effort, record_min_distance_m = excluded.record_min_distance_m, tracks_distance = excluded.tracks_distance, measure = excluded.measure, updated_at = now();

delete from public.exercise_skills where exercise_id in (select id from public.exercises where owner_user_id is null);


on conflict (id) do update set key = excluded.key, name = excluded.name, updated_at = now();

delete from public.program_days where program_id in (select id from public.programs where owner_user_id is null);



on conflict (id) do update set key = excluded.key, name = excluded.name, kind = excluded.kind, definition = excluded.definition, updated_at = now(), retired_at = case when excluded.retired_at is null then null else coalesce(challenges.retired_at, excluded.retired_at) end;

on conflict (id) do update set key = excluded.key, name = excluded.name, description = excluded.description, quest_points = excluded.quest_points, sort_order = excluded.sort_order, definition = excluded.definition, updated_at = now(), retired_at = case when excluded.retired_at is null then null else coalesce(quests.retired_at, excluded.retired_at) end;

on conflict (id) do update set key = excluded.key, name = excluded.name, kind = excluded.kind, rarity = excluded.rarity, tier = excluded.tier, gear_slot = excluded.gear_slot, icon_key = excluded.icon_key, description = excluded.description, grants_challenge_id = excluded.grants_challenge_id, sort_order = excluded.sort_order, updated_at = now(), retired_at = case when excluded.retired_at is null then null else coalesce(items.retired_at, excluded.retired_at) end;

on conflict (id) do update set key = excluded.key, name = excluded.name, updated_at = now(), retired_at = case when excluded.retired_at is null then null else coalesce(drop_tables.retired_at, excluded.retired_at) end;

delete from public.drop_entries;


on conflict (id) do update set key = excluded.key, output_item_id = excluded.output_item_id, output_quantity = excluded.output_quantity, updated_at = now(), retired_at = case when excluded.retired_at is null then null else coalesce(recipes.retired_at, excluded.retired_at) end;

delete from public.recipe_inputs;


